use super::*;

// ─── Chi-separation method params (cf/b0/se_echo_times are set from scan metadata) ───
/// χ-separation (iLSQR). Written out rather than generated by `param_config!` because
/// `qsm_ilsqr` is a group of its own.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(default)]
pub struct ChiSepIlsqrConfig {
    /// Relaxometric constants in Hz/ppm; `None` is the toolbox's 137 × B0/2.9 T.
    pub dr_pos: Option<f64>,
    pub dr_neg: Option<f64>,
    /// Zero padding at both ends of each axis, voxels (x y z).
    pub pad: [usize; 3],
    /// Step 1 (LSQR): CG iterations and relative tolerance.
    pub cg_max_iter_lsqr: usize,
    pub cg_tol_lsqr: f64,
    /// Step 2 (streaking removal): CG iterations and relative tolerance.
    pub cg_max_iter_sa: usize,
    pub cg_tol_sa: f64,
    /// The streaking cone is |D| < `d2_thr`.
    pub d2_thr: f64,
    /// Percentiles (0-100) of the field's Laplacian at which step 1's weight is 1 and 0.
    pub prc_w_i_min: f64,
    pub prc_w_i_max: f64,
    /// Percentiles (0-100) of each gradient's magnitude at which step 2's weights are 1 and 0.
    pub prc_w_g_min: f64,
    pub prc_w_g_max: f64,
    /// The iLSQR of the susceptibility map χ-separation is initialised with, reconstructed from
    /// the local field (unless a QSM is supplied): the χ-separation toolbox's call by default.
    pub qsm_ilsqr: IlsqrConfig,
}
impl Default for ChiSepIlsqrConfig {
    fn default() -> Self {
        let p = qsm_core::separation::ChiSepIlsqrParams::default();
        Self {
            dr_pos: p.dr_pos, dr_neg: p.dr_neg, pad: p.pad,
            cg_max_iter_lsqr: p.cg_max_iter_lsqr, cg_tol_lsqr: p.cg_tol_lsqr,
            cg_max_iter_sa: p.cg_max_iter_sa, cg_tol_sa: p.cg_tol_sa, d2_thr: p.d2_thr,
            prc_w_i_min: p.prc_w_i.0, prc_w_i_max: p.prc_w_i.1,
            prc_w_g_min: p.prc_w_g.0, prc_w_g_max: p.prc_w_g.1,
            qsm_ilsqr: IlsqrConfig::from(&p.qsm_ilsqr),
        }
    }
}
impl ChiSepIlsqrConfig {
    /// qsm-core's parameters (`cf` is the dispatcher's, from the scan).
    pub fn params(&self) -> qsm_core::separation::ChiSepIlsqrParams {
        qsm_core::separation::ChiSepIlsqrParams {
            dr_pos: self.dr_pos, dr_neg: self.dr_neg, pad: self.pad,
            cg_max_iter_lsqr: self.cg_max_iter_lsqr, cg_tol_lsqr: self.cg_tol_lsqr,
            cg_max_iter_sa: self.cg_max_iter_sa, cg_tol_sa: self.cg_tol_sa, d2_thr: self.d2_thr,
            prc_w_i: (self.prc_w_i_min, self.prc_w_i_max),
            prc_w_g: (self.prc_w_g_min, self.prc_w_g_max),
            qsm_ilsqr: self.qsm_ilsqr.params(),
            ..qsm_core::separation::ChiSepIlsqrParams::default()
        }
    }
}
/// χ-separation MEDI (the SNU toolbox's `chi_sep_MEDI`). Written out rather than generated by
/// `param_config!` because `qsm_ilsqr` is a group of its own.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(default)]
pub struct ChiSepMediConfig {
    pub lambda: f64,
    pub lambda_csf: f64,
    /// Relaxometric constants in Hz/ppm; `None` is the toolbox's 137 × B0/2.9 T.
    pub dr_pos: Option<f64>,
    pub dr_neg: Option<f64>,
    /// Voxels of zeros at both ends of the third axis.
    pub pad: usize,
    pub tol: f64,
    pub max_iter: usize,
    pub cg_tol: f64,
    pub cg_max_iter: usize,
    /// The iLSQR of the susceptibility map χ-separation is initialised with, reconstructed from
    /// the local field (unless a QSM is supplied): the χ-separation toolbox's call by default,
    /// the same as χ-sep iLSQR's.
    pub qsm_ilsqr: IlsqrConfig,
    /// The R2* the CSF mask is extracted from: `arlo` (default) or `nnls` (the χ-separation
    /// toolbox's `r2star_nnls`, as its script runs).
    pub csf_r2star: ChiSepCsfR2star,
}
impl Default for ChiSepMediConfig {
    fn default() -> Self {
        let p = qsm_core::separation::ChiSepMediParams::default();
        Self {
            lambda: p.lambda, lambda_csf: p.lambda_csf, dr_pos: p.dr_pos, dr_neg: p.dr_neg, pad: p.pad,
            tol: p.tol, max_iter: p.max_iter, cg_tol: p.cg_tol, cg_max_iter: p.cg_max_iter,
            qsm_ilsqr: IlsqrConfig::from(&p.qsm_ilsqr), csf_r2star: p.csf_r2star.into(),
        }
    }
}
impl ChiSepMediConfig {
    /// qsm-core's parameters (`cf` is the dispatcher's, from the scan).
    pub fn params(&self) -> qsm_core::separation::ChiSepMediParams {
        qsm_core::separation::ChiSepMediParams {
            lambda: self.lambda, lambda_csf: self.lambda_csf, dr_pos: self.dr_pos,
            dr_neg: self.dr_neg, pad: self.pad, tol: self.tol, max_iter: self.max_iter,
            cg_tol: self.cg_tol, cg_max_iter: self.cg_max_iter, qsm_ilsqr: self.qsm_ilsqr.params(),
            csf_r2star: self.csf_r2star.into(),
            ..qsm_core::separation::ChiSepMediParams::default()
        }
    }
}
param_config!(R2starQsmConfig from qsm_core::separation::R2starQsmParams { r_const_3t: f64 });
param_config!(WaveSepConfig from qsm_core::separation::WaveSepParams {
    dr_pos: f64, dr_neg: f64, alpha: f64, lambda: f64, wavelet_order: usize, max_iter: usize, tol: f64
});
// MATLAB `lsqcurvefit`'s options (trust-region-reflective), which every DECOMPOSE stage is solved
// with; MATLAB's defaults. `max_function_evaluations` `None` is MATLAB's 100 × the stage's number
// of parameters.
param_config!(LsqcurvefitConfig from qsm_core::solvers::LsqTrrOptions {
    max_iterations: usize, max_function_evaluations: Option<usize>, function_tolerance: f64,
    step_tolerance: f64, optimality_tolerance: f64, finite_difference_step: f64, typical_x: f64
});
impl LsqcurvefitConfig {
    /// qsm-core's options.
    pub fn options(&self) -> qsm_core::solvers::LsqTrrOptions {
        qsm_core::solvers::LsqTrrOptions {
            max_iterations: self.max_iterations,
            max_function_evaluations: self.max_function_evaluations,
            function_tolerance: self.function_tolerance,
            step_tolerance: self.step_tolerance,
            optimality_tolerance: self.optimality_tolerance,
            finite_difference_step: self.finite_difference_step,
            typical_x: self.typical_x,
        }
    }
}
/// DECOMPOSE-QSM. Written out rather than generated by `param_config!` because `lsqcurvefit` is a
/// group of its own. `unwrap_phase`: unwrap the phase along the echoes; off by default, as in the
/// authors' code. `chi_bound`: the bound on |χ| in the fit, a number in ppm (the authors' 0.5) or
/// `"echo-spacing"` ([`ChiBoundChoice`]).
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(default)]
pub struct DecomposeConfig {
    pub n_inner: usize,
    pub chi_bound: ChiBoundChoice,
    pub unwrap_phase: bool,
    pub lsqcurvefit: LsqcurvefitConfig,
    /// The reference code's fit (default) or the paper's, which the DECOMPOSE pipeline runs.
    #[serde(default)]
    pub fit: DecomposeFit,
}
impl Default for DecomposeConfig {
    fn default() -> Self {
        let p = qsm_core::separation::DecomposeParams::default();
        Self {
            n_inner: p.n_inner, chi_bound: p.chi_bound.into(), unwrap_phase: p.unwrap_phase,
            lsqcurvefit: LsqcurvefitConfig::default(), fit: DecomposeFit::default(),
        }
    }
}
param_config!(HcChisepConfig from qsm_core::separation::HcChisepParams {
    dr_pos_3t: f64, bin_hz: f64
});

/// Chi-separation configuration (algorithm selector + per-method params).
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(default)]
pub struct SeparationConfig {
    pub algorithm: SeparationAlgorithm,
    pub chi_sep_ilsqr: ChiSepIlsqrConfig,
    pub chi_sep_medi: ChiSepMediConfig,
    pub r2star_qsm: R2starQsmConfig,
    pub wavesep: WaveSepConfig,
    pub decompose: DecomposeConfig,
    pub hc_chisep: HcChisepConfig,
    /// Bring-your-own input maps from `<bids>/derivatives/<tool>/…` (mirrors
    /// `masking.custom_mask_tool`). When set, the pipeline prefers the custom map over
    /// computing it. Empty/None = compute from the pipeline.
    #[serde(default)]
    pub custom_qsm_tool: Option<String>,
    #[serde(default)]
    pub custom_r2_tool: Option<String>,
    #[serde(default)]
    pub custom_r2prime_tool: Option<String>,
    /// How R2′ is obtained when `custom_r2prime_tool` supplies nothing. A custom map always wins;
    /// this decides between measuring R2′ from a MESE acquisition and predicting it with
    /// R2PRIMEnet.
    #[serde(default)]
    pub r2prime_strategy: R2PrimeStrategy,
    /// R2PRIMEnet inference settings, for when R2′ is predicted rather than measured.
    #[serde(default)]
    pub r2primenet: R2primenetConfig,
    /// χ-sepnet inference settings.
    #[serde(default)]
    pub chi_sepnet: ChiSepNetConfig,
    /// SUSEP-Net inference settings.
    #[serde(default)]
    pub susep_net: SusepNetConfig,
}

/// χ-sepnet inference (`qsm_core::separation::ChiSepNetParams`).
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(default)]
pub struct ChiSepNetConfig {
    /// The input route: the authors' (`toolbox`, default) or the network alone (`native`).
    pub route: ChiSepNetRoute,
    /// `native`: the sliding-window patch (D, H, W) in voxels; each a positive multiple of 16.
    pub patch: [usize; 3],
    /// `toolbox`: run each network as a sliding window of this patch over the training frame
    /// (each a positive multiple of 16); `None` (default) runs the whole frame at once, as the
    /// authors do.
    pub frame_patch: Option<[usize; 3]>,
}
impl Default for ChiSepNetConfig {
    fn default() -> Self {
        let p = qsm_core::separation::ChiSepNetParams::default();
        let (d, h, w) = p.patch;
        Self { route: ChiSepNetRoute::default(), patch: [d, h, w], frame_patch: p.frame_patch.map(|(d, h, w)| [d, h, w]) }
    }
}
impl ChiSepNetConfig {
    /// Why the route's patch cannot be used, if it cannot (QSM.rs's `ChiSepNetParams::validate`).
    pub fn validate(&self) -> Result<(), String> {
        self.params().validate()
    }
    /// qsm-core's parameters for these settings. Each route reads one patch: the other's value is
    /// a hidden setting, left at qsm-core's default so what is left behind in it cannot stop a run
    /// or hide a problem with the patch in use (#495).
    pub fn params(&self) -> qsm_core::separation::ChiSepNetParams {
        let d = qsm_core::separation::ChiSepNetParams::default();
        let [pd, ph, pw] = self.patch;
        let (route, patch, frame_patch) = match self.route {
            ChiSepNetRoute::Toolbox => (qsm_core::separation::ChiSepNetRoute::Toolbox, d.patch, self.frame_patch.map(|[d, h, w]| (d, h, w))),
            ChiSepNetRoute::Native => (qsm_core::separation::ChiSepNetRoute::Native, (pd, ph, pw), d.frame_patch),
        };
        qsm_core::separation::ChiSepNetParams { route, patch, frame_patch, ..d }
    }
}

/// SUSEP-Net inference (`qsm_core::separation::SusepNetParams`).
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Default)]
#[serde(default)]
pub struct SusepNetConfig {
    /// Sliding-window patch (D, H, W) in voxels, each a positive multiple of 8; `None` (the
    /// default) runs the whole volume in one pass.
    pub patch: Option<[usize; 3]>,
}
impl SusepNetConfig {
    /// Why the patch cannot be used, if it cannot (QSM.rs's `SusepNetParams::validate`).
    pub fn validate(&self) -> Result<(), String> {
        self.params().validate()
    }
    /// qsm-core's parameters for these settings.
    pub fn params(&self) -> qsm_core::separation::SusepNetParams {
        qsm_core::separation::SusepNetParams { patch: self.patch.map(|[d, h, w]| (d, h, w)) }
    }
}

/// R2PRIMEnet inference (`qsm_core::relaxometry::R2PrimeNetParams`).
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(default)]
pub struct R2primenetConfig {
    /// Sliding-window patch (D, H, W) in voxels; each a positive multiple of 16.
    pub patch: [usize; 3],
    /// Run even though the acquisition is not at 3 T, the only field strength the weights were
    /// trained at. The R2′ is then uncalibrated. Off by default: an explicit
    /// `r2prime_strategy = "r2primenet"` then refuses a non-3 T run, and `auto` skips R2′.
    pub ignore_field_mismatch: bool,
}
impl Default for R2primenetConfig {
    fn default() -> Self {
        let core = qsm_core::relaxometry::R2PrimeNetParams::default();
        let (d, h, w) = core.patch;
        Self { patch: [d, h, w], ignore_field_mismatch: core.ignore_field_mismatch }
    }
}
impl R2primenetConfig {
    /// Why the patch cannot be used, if it cannot (qsm-core panics on it).
    pub fn validate(&self) -> Result<(), String> {
        use qsm_core::relaxometry::POOL_MULTIPLE;
        for (axis, v) in ["D", "H", "W"].into_iter().zip(self.patch) {
            if v == 0 || v % POOL_MULTIPLE != 0 {
                return Err(format!(
                    "R2PRIMEnet patch {axis} = {v} must be a positive multiple of {POOL_MULTIPLE} (four pooling levels)"));
            }
        }
        Ok(())
    }
}
impl Default for SeparationConfig {
    fn default() -> Self {
        Self {
            algorithm: SeparationAlgorithm::R2starQsm,
            chi_sep_ilsqr: ChiSepIlsqrConfig::default(),
            chi_sep_medi: ChiSepMediConfig::default(),
            r2star_qsm: R2starQsmConfig::default(),
            wavesep: WaveSepConfig::default(),
            decompose: DecomposeConfig::default(),
            hc_chisep: HcChisepConfig::default(),
            custom_qsm_tool: None,
            custom_r2_tool: None,
            custom_r2prime_tool: None,
            r2prime_strategy: R2PrimeStrategy::default(),
            r2primenet: R2primenetConfig::default(),
            chi_sepnet: ChiSepNetConfig::default(),
            susep_net: SusepNetConfig::default(),
        }
    }
}
